        if not m:
            return []
        return re.findall(r'\[\[.*?\]\]', m.group(1))
    parents=parse('Parents')
    deps=parse('Dependencies')
    succ=parse('Successors')
    # split header/body
    lines=text.splitlines()
    header_end=0
    for i,line in enumerate(lines):
        if line.startswith('# '):
            header_end=i
            break
    header=lines[:header_end]
    body=lines[header_end:]
    def replace_field(hdr,label,items):
        # remove existing label line and following continuation lines starting with space and [
