                    arr=', '.join(f'"{i}"' for i in items)
                else:
                    arr=''
                new_hdr.append(f'{label}: [{arr}]')
            else:
                new_hdr.append(line)
        return new_hdr
    header=replace_field(header,'parents',parents)
    header=replace_field(header,'dependencies',deps)
    header=replace_field(header,'successors',succ)
    new_text='\n'.join(header+body)+"\n"
